begin;
create function private.profile_visible(tid uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.profiles where id=tid and not private.blocked(auth.uid(),tid)and(visibility='public'or tid=auth.uid()or exists(select 1 from public.user_follows where user_id=auth.uid()and target_id=tid and status='active')))$$;
revoke all on function private.profile_visible(uuid)from public;
grant execute on function private.profile_visible(uuid)to anon,authenticated;
alter policy profile_read on public.profiles using(private.profile_visible(id));
create function private.creator_json(tid uuid)returns jsonb language sql stable security definer set search_path='' as $$select jsonb_build_object('id',p.id,'username',p.username,'display_name',p.display_name,'bio',p.bio,'interests',p.interests,'avatar_path',p.avatar_path,'banner_path',p.banner_path,'accent',p.accent,'layout',p.layout,'social_links',p.social_links,'visibility',p.visibility,'follower_count',(select count(*)from public.user_follows where target_id=tid and status='active'),'following_count',(select count(*)from public.user_follows where user_id=tid and status='active'),'post_count',(select count(*)from public.posts where author_id=tid and deleted_at is null and private.post_visible(id)),'following',exists(select 1 from public.user_follows where user_id=auth.uid()and target_id=tid),'follows_you',exists(select 1 from public.user_follows where user_id=tid and target_id=auth.uid()and status='active'))from public.profiles p where id=tid and private.profile_visible(tid)$$;
create function private.world_json(wid uuid)returns jsonb language sql stable security definer set search_path='' as $$select to_jsonb(w)||jsonb_build_object('member_count',(select count(*)from public.world_members where world_id=wid),'joined',exists(select 1 from public.world_members where world_id=wid and user_id=auth.uid()),'role',(select role from public.world_members where world_id=wid and user_id=auth.uid()),'preferences',(select to_jsonb(p)-'user_id'from public.world_preferences p where world_id=wid and user_id=auth.uid()),'post_count',(select count(*)from public.post_worlds pw where pw.world_id=wid and pw.status='published'and private.post_visible(pw.post_id)))from public.worlds w where id=wid and private.world_visible(wid)$$;
create function private.community_json(cid uuid)returns jsonb language sql stable security definer set search_path='' as $$select to_jsonb(c)||jsonb_build_object('member_count',(select count(*)from public.community_members where community_id=cid and status='active'),'role',(select role from public.community_members where community_id=cid and user_id=auth.uid()),'membership',(select status from public.community_members where community_id=cid and user_id=auth.uid()),'world_ids',coalesce((select jsonb_agg(world_id)from public.community_worlds where community_id=cid and private.world_visible(world_id)),'[]'))from public.communities c where id=cid and private.community_visible(cid)$$;
create function private.post_json(pid uuid)returns jsonb language sql stable security definer set search_path='' as $$select to_jsonb(p)||jsonb_build_object('author',private.creator_json(p.author_id),'worlds',coalesce((select jsonb_agg(jsonb_build_object('id',w.id,'name',w.name,'icon',w.icon))from public.post_worlds pw join public.worlds w on w.id=pw.world_id where pw.post_id=pid and pw.status='published'and private.world_visible(w.id)),'[]'),'community',case when p.community_id is not null then private.community_json(p.community_id)else null end,'media',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'path',m.path,'kind',m.kind,'mime',m.mime,'duration_seconds',m.duration_seconds,'alt',pm.alt_text,'position',pm.position)order by pm.position)from public.post_media pm join public.uploaded_media m on m.id=pm.media_id where pm.post_id=pid and m.status='ready'),'[]'),'likes',(select count(*)from public.post_likes where post_id=pid),'comments',(select count(*)from public.post_comments where post_id=pid and deleted_at is null),'saves',(select count(*)from public.post_saves where post_id=pid),'reposts',(select count(*)from public.post_reposts where post_id=pid),'shares',(select count(*)from public.post_shares where post_id=pid),'views',(select count(*)from public.post_impressions where post_id=pid),'liked',exists(select 1 from public.post_likes where post_id=pid and user_id=auth.uid()),'saved',exists(select 1 from public.post_saves where post_id=pid and user_id=auth.uid()),'reposted',exists(select 1 from public.post_reposts where post_id=pid and user_id=auth.uid()),'vote',(select option_index from public.post_votes where post_id=pid and user_id=auth.uid()),'poll_results',coalesce((select jsonb_agg(jsonb_build_object('option',v.option_index,'votes',v.n))from(select option_index,count(*)n from public.post_votes where post_id=pid group by option_index)v),'[]'),'quoted',case when private.post_visible(p.quoted_post_id)then(select jsonb_build_object('id',q.id,'body',q.body,'title',q.title,'author',private.creator_json(q.author_id))from public.posts q where q.id=p.quoted_post_id)else null end)from public.posts p where p.id=pid and private.post_visible(pid)$$;
create function private.social_read(operation text,payload jsonb default '{}')returns jsonb language plpgsql stable security definer set search_path='' as $$
declare uid uuid:=auth.uid();wid uuid:=nullif(payload->>'world_id','')::uuid;cid uuid:=nullif(payload->>'community_id','')::uuid;tid uuid:=nullif(payload->>'target_id','')::uuid;pid uuid:=nullif(payload->>'post_id','')::uuid;rid uuid;result jsonb;items jsonb;cursor_value jsonb;w public.worlds;mix jsonb;sorting text:=coalesce(payload->>'sort','balanced');small boolean:=coalesce((payload->>'small_creators')::boolean,true);followed_only boolean:=coalesce((payload->>'followed_communities')::boolean,false);tab text:=coalesce(payload->>'tab','For You');profile_interests text[];begin
 if operation='bootstrap'then
 return jsonb_build_object('worlds',coalesce((select jsonb_agg(private.world_json(id)order by case when owner_id=uid then 0 else 1 end,created_at desc)from(select * from public.worlds where private.world_visible(id)order by created_at desc limit 50)w),'[]'),'creators',coalesce((select jsonb_agg(private.creator_json(id))from(select p.id from public.profiles p where p.id is distinct from uid and p.visibility='public'and p.onboarded and private.profile_visible(p.id)order by (select count(*)from public.posts where author_id=p.id and deleted_at is null)desc,p.created_at desc limit 8)p),'[]'),'communities',coalesce((select jsonb_agg(private.community_json(id))from(select id from public.communities where private.community_visible(id)order by created_at desc limit 30)c),'[]'),'following_ids',coalesce((select jsonb_agg(target_id)from public.user_follows where user_id=uid and status='active'),'[]'));
 elsif operation='feed'then
 if wid is not null then
 if not private.world_visible(wid)then raise exception 'World unavailable';end if;select * into w from public.worlds where id=wid;
 select coalesce(p.content_mix,w.content_mix),coalesce(p.sort,sorting),coalesce(p.small_creators,small),coalesce(p.followed_communities,followed_only)into mix,sorting,small,followed_only from public.world_preferences p where p.world_id=wid and p.user_id=uid;
 if not found then mix:=w.content_mix;end if;
 end if;
 mix:=coalesce(mix,'{"video":30,"image":25,"text":25,"community":20}');
 select interests into profile_interests from public.profiles where id=uid;
 with eligible as(select p.*,
 (select count(*)from public.user_follows f where target_id=p.author_id and f.status='active')follower_count,
 (select count(*)from public.post_likes l where l.post_id=p.id and l.created_at>now()-interval '7 days')+2*(select count(*)from public.post_comments c where c.post_id=p.id and c.created_at>now()-interval '7 days'and c.deleted_at is null)engagement,
 exists(select 1 from public.user_follows f where f.user_id=uid and f.target_id=p.author_id and f.status='active')following
 from public.posts p where private.post_visible(p.id)
 and(tab not in('Videos','Images','Discussions')or p.type=case tab when 'Videos'then 'video'when 'Images'then 'image'else 'text'end or(tab='Discussions'and p.type='poll'))
 and(tab<>'Saved'or exists(select 1 from public.post_saves s where s.post_id=p.id and s.user_id=uid))
 and(tab<>'Following'or exists(select 1 from public.user_follows f where f.user_id=uid and f.target_id=p.author_id and f.status='active')or exists(select 1 from public.post_worlds pw join public.world_members wm on wm.world_id=pw.world_id where pw.post_id=p.id and wm.user_id=uid and pw.status='published')or exists(select 1 from public.post_reposts pr join public.user_follows f on f.target_id=pr.user_id where pr.post_id=p.id and f.user_id=uid and f.status='active'))
 and(tid is null or p.author_id=tid)
 and(cid is null or(p.community_id=cid and private.community_visible(cid)))
 and(wid is null or(w.kind='public'and exists(select 1 from public.post_worlds pw where pw.post_id=p.id and pw.world_id=wid and pw.status='published'))or(w.kind='personal'and(p.topics&&w.topics or p.topics&&array[w.category]or exists(select 1 from public.user_follows f where f.user_id=uid and f.target_id=p.author_id and f.status='active'))))
 and(not followed_only or exists(select 1 from public.community_members cm where cm.community_id=p.community_id and cm.user_id=uid and cm.status='active'))
 and(coalesce(payload->>'query','')=''or p.body ilike '%'||(payload->>'query')||'%'or p.title ilike '%'||(payload->>'query')||'%'or exists(select 1 from unnest(p.topics)t where t ilike '%'||(payload->>'query')||'%'))
 ),ranked as(select e.*,
 case when sorting='newest'or tab in('Recent','Following')then 0::numeric
 when sorting='popular'then ln(1+engagement)::numeric
 else(case when following then 3 else 0 end+case when topics&&coalesce(profile_interests,'{}')then 2 else 0 end+ln(1+engagement)+coalesce((mix->>case when community_id is not null then 'community'else type end)::numeric,0)/greatest(1,coalesce((mix->>'video')::numeric,0)+coalesce((mix->>'image')::numeric,0)+coalesce((mix->>'text')::numeric,0)+coalesce((mix->>'community')::numeric,0))*3+1/(1+extract(epoch from(now()-created_at))/86400))::numeric end rank_score
 from eligible e where small or follower_count>=100 or following or author_id=uid),page as(select * from ranked where payload->'cursor'is null or payload->'cursor'='null'::jsonb or(rank_score,created_at,id)<((payload->'cursor'->>'score')::numeric,(payload->'cursor'->>'created_at')::timestamptz,(payload->'cursor'->>'id')::uuid)order by rank_score desc,created_at desc,id desc limit 18)
 select coalesce(jsonb_agg(private.post_json(id)||jsonb_build_object('rank_score',rank_score)order by rank_score desc,created_at desc,id desc),'[]'),(select jsonb_build_object('score',rank_score,'created_at',created_at,'id',id)from page order by rank_score asc,created_at asc,id asc limit 1)into items,cursor_value from page;
 return jsonb_build_object('items',items,'cursor',case when jsonb_array_length(items)=18 then cursor_value else null end);
 elsif operation='post'then return coalesce(private.post_json(pid),'null');
 elsif operation='comments'then
 if not private.post_visible(pid)then raise exception 'Post unavailable';end if;
 return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('author',private.creator_json(c.author_id))order by c.created_at)from(select * from public.post_comments c where post_id=pid and not private.blocked(uid,author_id)and(payload->>'before'is null or c.created_at<(payload->>'before')::timestamptz)order by created_at desc limit 80)c),'[]');
 elsif operation='world'then
 if not private.world_visible(wid)then raise exception 'World unavailable';end if;
 return jsonb_build_object('world',private.world_json(wid),'members',coalesce((select jsonb_agg(jsonb_build_object('user',private.creator_json(user_id),'role',role))from public.world_members where world_id=wid and not private.blocked(uid,user_id)),'[]'),'communities',coalesce((select jsonb_agg(private.community_json(community_id))from public.community_worlds where world_id=wid and private.community_visible(community_id)),'[]'),'pending',case when private.world_manager(wid)then coalesce((select jsonb_agg(private.post_json(post_id))from public.post_worlds where world_id=wid and status='pending'and private.post_visible(post_id)),'[]')else '[]'end,'reports',case when private.world_manager(wid)then coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'post_id',r.post_id,'reason',r.reason,'created_at',r.created_at))from public.reports r where r.world_id=wid),'[]')else '[]'end);
 elsif operation='community'then
 if not private.community_visible(cid)then raise exception 'Community unavailable';end if;
 return jsonb_build_object('community',private.community_json(cid),'members',coalesce((select jsonb_agg(jsonb_build_object('user',private.creator_json(user_id),'role',role,'status',status))from public.community_members where community_id=cid and(status='active'or private.community_manager(cid))and not private.blocked(uid,user_id)),'[]'));
 elsif operation='profile'then
 if not private.profile_visible(tid)then raise exception 'Profile is private or unavailable';end if;
 return jsonb_build_object('profile',private.creator_json(tid),'worlds',coalesce((select jsonb_agg(private.world_json(id))from public.worlds where owner_id=tid and private.world_visible(id)),'[]'),'requests',case when uid=tid then coalesce((select jsonb_agg(private.creator_json(user_id))from public.user_follows where target_id=uid and status='pending'),'[]')else '[]'end);
 elsif operation='search'then
 return jsonb_build_object('creators',coalesce((select jsonb_agg(private.creator_json(id))from(select id from public.profiles where private.profile_visible(id)and(display_name ilike '%'||coalesce(payload->>'query','')||'%'or username ilike '%'||coalesce(payload->>'query','')||'%')order by display_name limit 30)p),'[]'),'worlds',coalesce((select jsonb_agg(private.world_json(id))from(select id from public.worlds where private.world_visible(id)and(name ilike '%'||coalesce(payload->>'query','')||'%'or category ilike '%'||coalesce(payload->>'query','')||'%')limit 30)w),'[]'),'communities',coalesce((select jsonb_agg(private.community_json(id))from(select id from public.communities where private.community_visible(id)and name ilike '%'||coalesce(payload->>'query','')||'%'limit 30)c),'[]'));
 elsif operation='conversations'then
 if uid is null then raise exception 'Sign in to open your inbox';end if;
 return coalesce((select jsonb_agg(to_jsonb(c)||jsonb_build_object('members',(select jsonb_agg(private.creator_json(user_id))from public.conversation_members where conversation_id=c.id),'last_message',(select jsonb_build_object('body',body,'created_at',created_at)from public.direct_messages where conversation_id=c.id order by created_at desc limit 1),'unread',(select count(*)from public.direct_messages d join public.conversation_members cm on cm.conversation_id=d.conversation_id where d.conversation_id=c.id and cm.user_id=uid and d.author_id<>uid and d.created_at>coalesce(cm.read_at,'1970-01-01')),'muted',(select muted from public.conversation_members where conversation_id=c.id and user_id=uid))order by c.created_at desc)from public.conversations c where private.conversation_member(c.id)),'[]');
 elsif operation='conversation'then
 rid:=(payload->>'conversation_id')::uuid;if not private.conversation_member(rid)then raise exception 'Conversation unavailable';end if;
 return jsonb_build_object('messages',coalesce((select jsonb_agg(to_jsonb(d)||jsonb_build_object('author',private.creator_json(d.author_id))order by d.created_at)from(select * from public.direct_messages d where conversation_id=rid and(payload->>'before'is null or created_at<(payload->>'before')::timestamptz)order by created_at desc limit 50)d),'[]'),'members',(select jsonb_agg(jsonb_build_object('user',private.creator_json(cm.user_id),'read_at',case when(select read_receipts from public.user_settings where user_id=cm.user_id)then cm.read_at else null end))from public.conversation_members cm where conversation_id=rid));
 elsif operation='analytics'then
 if uid is null then raise exception 'Sign in to see your analytics';end if;
 return jsonb_build_object('views',(select count(*)from public.post_impressions i join public.posts p on p.id=i.post_id where p.author_id=uid and i.created_at>now()-make_interval(days=>least(90,greatest(1,coalesce((payload->>'days')::integer,30))))),'likes',(select count(*)from public.post_likes l join public.posts p on p.id=l.post_id where p.author_id=uid and l.created_at>now()-make_interval(days=>least(90,greatest(1,coalesce((payload->>'days')::integer,30))))),'comments',(select count(*)from public.post_comments c join public.posts p on p.id=c.post_id where p.author_id=uid and c.deleted_at is null),'shares',(select count(*)from public.post_shares s join public.posts p on p.id=s.post_id where p.author_id=uid),'saves',(select count(*)from public.post_saves s join public.posts p on p.id=s.post_id where p.author_id=uid),'followers',(select count(*)from public.user_follows where target_id=uid and status='active'),'profile_visits',(select count(*)from public.profile_visits where profile_id=uid),'top_posts',coalesce((select jsonb_agg(private.post_json(id))from(select p.id from public.posts p where author_id=uid and deleted_at is null order by(select count(*)from public.post_impressions where post_id=p.id)desc limit 5)p),'[]'),'growth',coalesce((select jsonb_agg(jsonb_build_object('day',d,'followers',n))from(select created_at::date d,count(*)n from public.user_follows where target_id=uid and status='active'group by created_at::date order by d)g),'[]'),'distribution',coalesce((select jsonb_agg(jsonb_build_object('world',w.name,'posts',(select count(*)from public.post_worlds pw join public.posts p on p.id=pw.post_id where pw.world_id=w.id and p.author_id=uid and pw.status='published')))from public.worlds w where private.world_visible(w.id)and exists(select 1 from public.post_worlds pw join public.posts p on p.id=pw.post_id where pw.world_id=w.id and p.author_id=uid)),'[]'));
 end if;raise exception 'Unknown resource';
end$$;
create function public.social_read(operation text,payload jsonb default '{}')returns jsonb language sql security invoker set search_path='' as $$select private.social_read(operation,payload)$$;
revoke all on function private.creator_json(uuid),private.world_json(uuid),private.community_json(uuid),private.post_json(uuid),private.social_read(text,jsonb),public.social_read(text,jsonb)from public;
grant execute on function private.social_read(text,jsonb),public.social_read(text,jsonb)to anon,authenticated;
commit;
